// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product} from "../src/Product.sol";

contract InvMutTest is Test {
    Product c;
    Initializer init;
    OracleMock oracleA;
    OracleMock oracleB;

    function setUp() public {
        c = new Product();
        init = new Initializer();
        oracleA = new OracleMock();
        oracleB = new OracleMock();
    }

    function testFuzz_property(uint256 seed) public {
        // Fuzzer picks which deployed oracle contract is configured.
        uint256 pick = bound(seed, 0, 1);
        OracleMock chosen = pick == 0 ? oracleA : oracleB;

        // Initialize through a helper contract so msg.sender (the controller
        // argument) is a contract with code, as the reference requires.
        init.doInitialize(address(c), address(chosen));

        // GENERAL RULE: oracle() returns the configured oracle address
        // (non-zero, a real deployed contract) for ANY admissible config.
        assertTrue(
            address(c.oracle()) == address(chosen) && address(chosen) != address(0),
            "oracle() must return the configured oracle contract"
        );
    }
}

contract OracleMock {
    // minimal contract with runtime code; satisfies Address.isContract
}

contract Initializer {
    // mirrored ABI of IProduct.ProductInfo (user-defined value types share ABI
    // representations with their underlying types)
    struct PayoffDefinition {
        uint8 payoffType;
        uint8 payoffDirection;
        bytes30 data;
    }

    struct JumpRateUtilizationCurve {
        int128 minRate;
        int128 maxRate;
        int128 targetRate;
        uint128 targetUtilization;
    }

    struct ProductInfo {
        string name;
        string symbol;
        PayoffDefinition payoffDefinition;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        JumpRateUtilizationCurve utilizationCurve;
    }

    function doInitialize(address target, address oracle_) external {
        ProductInfo memory info;
        info.name = "T";
        info.symbol = "T";
        info.oracle = oracle_;
        IInit(target).initialize(info);
    }
}

interface IInit {
    function initialize(Initializer.ProductInfo calldata productInfo_) external;
}
